List<User> users = getProductionUsers();

// Efficient, readable sorting using method references
users.sort(Comparator.comparing(User::getLastName)
                     .thenComparing(User::getRegistrationDate, Comparator.reverseOrder()));

// Legacy style for complex logic
users.sort((u1, u2) -> {
    int res = u1.getDepartment().compareTo(u2.getDepartment());
    return (res != 0) ? res : Double.compare(u2.getSalary(), u1.getSalary());
});
